/* eslint-disable no-invalid-this */

'use strict';

// MAIN //

/**
* Returns the array of point for axis.
*
* @private
* @param {Array} range range of the value for which we need points
* @param {Number} dataPoints number of points we need
* @returns {Array} scale data points between range
*/
function linearScale( range, dataPoints ) {
	var arr;
	var i;
	var d;

	arr = [];
	i = range[ 0 ];
	d = ( range[ 1 ] - range[ 0 ] ) / dataPoints;
	while ( i <= range[ 1 ] ) {
		arr.push( i );
		i += d;
	}
	return arr;
}


// EXPORTS //

module.exports = linearScale;
